import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import AuthForm from '../../components/Form/AuthForm';
import './Auth.css';
import heroImg from '../../assets/images/Homepage.jpg';

interface SignUpFormValues {
  fullName: string;
  email: string;
  password: string;
  [key: string]: string;
}

const SignUp: React.FC = () => {
  const navigate = useNavigate();
  const { signup } = useAuth();

  const handleSignup = async (form: SignUpFormValues) => {
    const newUser = await signup(form.fullName, form.email, form.password);
    navigate(`/profile/${newUser.uid}`);
  };

  return (
    <div className="auth-layout">
      <div className="auth-left">
        <div className="auth-modal">
          <AuthForm<SignUpFormValues>
            title="Create an account"
            fields={[
              {
                name: 'fullName',
                label: 'Full Name',
                type: 'text',
                placeholder: 'John Doe',
              },
              {
                name: 'email',
                label: 'Email address',
                type: 'email',
                placeholder: 'you@example.com',
              },
              {
                name: 'password',
                label: 'Password',
                type: 'password',
                placeholder: '••••••••',
              },
            ]}
            submitText="Sign Up"
            loadingText="Creating Account..."
            onSubmit={handleSignup}
            footerText="Already have an account?"
            footerActionText="Log in"
            onFooterClick={() => navigate('/login')}
          />
        </div>
      </div>
      <div className="auth-right">
        <div className="auth-hero">
          <img src={heroImg} alt="Hero" className="auth-hero-img" />
        </div>
      </div>
    </div>
  );
};

export default SignUp;
